"""Brute-force cross-check of the canonical image against direct evaluation."""
import sys, itertools
sys.path.insert(0, '/workspace/project')
from syntax import parse, PolicyError
import compiler.compiler as C

DENY = C.DENY


def make_eval(cols):
    def ev(node, word):
        tag = node[0]
        if tag == 'and':
            return ev(node[1], word) and ev(node[2], word)
        if tag == 'or':
            return ev(node[1], word) or ev(node[2], word)
        if tag == 'not':
            return not ev(node[1], word)
        path = tuple(cols[n] for n in node[1])
        if tag == 'match':
            return path == word
        if tag == 'startswith':
            return word[:len(path)] == path
        if tag == 'endswith':
            return (word[-len(path):] == path) if path else True
        if tag == 'contains':
            if not path:
                return True
            m = len(path)
            return any(word[i:i+m] == path for i in range(len(word) - m + 1))
        raise AssertionError(tag)
    return ev


def lang_of(rules, ev, word):
    allows = [r for r in rules if r[1]]
    drops = [r for r in rules if not r[1]]
    if not allows:
        return False
    if not any(ev(p, word) for p, _ in allows):
        return False
    if any(ev(p, word) for p, _ in drops):
        return False
    return True


def image(text, cols):
    rules, a, p = parse(text)
    expr = C.language(rules, cols)
    t, acc = C.automaton(expr, len(cols))
    cls = C.minimize(t, acc)
    return C.canonical(t, acc, cls, len(cols))


def advance(rows, state, word):
    for c in word:
        if state == DENY:
            return DENY
        state = rows[state][c]
    return state


def check(text, names, limit=6, depth=6):
    k = len(names)
    cols = dict((n, i) for i, n in enumerate(names))
    ev = make_eval(cols)
    rules, _, _ = parse(text)
    flags, rows = image(text, cols)
    n = len(rows)
    # 1. language agreement
    for m in range(limit + 1):
        for word in itertools.product(range(k), repeat=m):
            st = advance(rows, 0, word)
            got = (st != DENY and flags[st])
            want = lang_of(rules, ev, word)
            if got != want:
                return 'language mismatch at %r: got %s want %s' % (word, got, want)
    # 2. only START may fail to reach acceptance
    reach = set(i for i in range(n) if flags[i])
    changed = True
    while changed:
        changed = False
        for i in range(n):
            if i in reach:
                continue
            if any(t != DENY and t in reach for t in rows[i]):
                reach.add(i); changed = True
    if not reach <= set(range(n)):
        return 'bad reach set'
    for i in set(range(n)) - reach:
        if i != 0:
            return 'retained dead state %d' % i
    # 3. distinct states are distinguishable (START..n-1 plus DENY)
    sig = {}
    for i in list(range(n)) + [DENY]:
        parts = []
        for m in range(depth + 1):
            for word in itertools.product(range(k), repeat=m):
                st = advance(rows, i, word)
                parts.append(False if st == DENY else flags[st])
        sig[i] = tuple(parts)
    seen = {}
    for i, s in sig.items():
        if s in seen:
            return 'states %r and %r equivalent (non-minimal?)' % (seen[s], i)
        seen[s] = i
    # 4. BFS numbering from START, columns in order, ignoring DENY
    order = [0]
    marked = {0}
    head = 0
    while head < len(order):
        s = order[head]; head += 1
        for c in range(k):
            t = rows[s][c]
            if t != DENY and t not in marked:
                marked.add(t); order.append(t)
    if order != list(range(n)):
        return 'BFS order mismatch: %r' % (order,)
    return None


if __name__ == '__main__':
    names = ['A', 'B']
    cases = [
        '', 'match(A) allow;', 'match(A) allow; match(A) drop;',
        'startswith(A) allow;', 'endswith(A) allow;', 'contains(A,B) allow;',
        'not(contains(A)) allow;', 'match(A,B) allow; match(B,A) allow;',
        '((match(A) or match(B)) and not(match(A))) allow;',
        'contains(A) drop; startswith(B) allow;',
        'match() allow;', 'startswith() allow;', 'contains() drop; match(A) allow;',
        'endswith(A,B) allow; not(endswith(B,A)) allow;',
        '((contains(A) and contains(B)) or match(A,A)) allow;',
        'not(startswith(A)) and not(endswith(B)) allow; contains(B) drop;',
        'match(A) drop; match(B) drop; startswith(A,A) allow;',
        'endswith() allow; match(A,B,A) drop;',
        'not(match()) allow;', 'not(match(A)) allow;',
        '(contains(A) and not(contains(A,B))) allow;',
        'match(B) allow; match(A,B) allow; match(B,B) allow;',
        '(not(match(A)) and not(match(B))) allow;',
        'contains(A,A) drop;', 'startswith(A,B) or endswith(B,A) allow;',
        'not(not(match(A))) allow;', 'match(A,A,A) allow; contains(B) drop;',
    ]
    bad = 0
    for text in cases:
        err = check(text, names)
        if err:
            bad += 1
            print('FAIL %r: %s' % (text, err))
    print('checked', len(cases), 'policies,', bad, 'failures')
PYEOF
